import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabaseClient";
import { Button } from "@/components/ui/button";
import NavBar from "@/components/nav-bar";
// import { ImageUploader } from "@/components/image-uploader";


// Wrapper para obtener la URL subida y guardarla en imageUrl
export function ImageUploaderWithUrl({ setImageUrl }: { setImageUrl: (url: string) => void }) {
  const [preview, setPreview] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setPreview(URL.createObjectURL(file));
    setLoading(true);
    const data = new FormData();
    data.append("file", file);
    const res = await fetch("/api/upload", {
      method: "POST",
      body: data,
    });
    const json = await res.json();
    setLoading(false);
    if (json.url) {
      setImageUrl(json.url);
    }
  };

  return (
    <div className="flex flex-col items-center">
      <input type="file" onChange={handleChange} />
      {loading && <span className="text-xs text-gray-500">Subiendo...</span>}
      {preview && (
        <img src={preview} alt="Preview" className="w-16 h-16 object-cover rounded mt-2" />
      )}
    </div>
  );
}

export default function AdminPerfumes() {
    const [formError, setFormError] = useState("");
  const [perfumes, setPerfumes] = useState<any[]>([]);
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("");
  const [imageUrl, setImageUrl] = useState("");
  const [loading, setLoading] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [editName, setEditName] = useState("");
  const [editDescription, setEditDescription] = useState("");
  const [editPrice, setEditPrice] = useState("");
  const [editImageUrl, setEditImageUrl] = useState("");

  useEffect(() => {
    fetchPerfumes();
  }, []);

  async function fetchPerfumes() {
    setLoading(true);
    const { data, error } = await supabase
      .from("products")
      .select("*")
      .eq("type", "perfume");
    if (!error) setPerfumes(data || []);
    setLoading(false);
  }

  async function addPerfume() {
    setFormError("");
    // Validaciones
    if (!name.trim() || !description.trim() || !price.trim() || !imageUrl.trim()) {
      setFormError("Todos los campos son obligatorios, incluyendo la imagen.");
      return;
    }
    const priceNum = Number(price);
    if (isNaN(priceNum) || priceNum <= 0) {
      setFormError("El precio debe ser un número positivo.");
      return;
    }
    setLoading(true);
    const { error } = await supabase.from("products").insert({
      name,
      type: "perfume",
      description,
      price: priceNum,
      image_url: imageUrl,
    });
    setLoading(false);
    if (error) {
      setFormError("Error al guardar el perfume. Intenta de nuevo.");
      return;
    }
    setName("");
    setDescription("");
    setPrice("");
    setImageUrl("");
    await fetchPerfumes();
  }

  async function deletePerfume(id: string) {
    setLoading(true);
    await supabase.from("products").delete().eq("id", id);
    await fetchPerfumes();
    setLoading(false);
  }

  async function updatePerfume(id: string) {
    setLoading(true);
    await supabase
      .from("products")
      .update({
        name: editName,
        description: editDescription,
        price: editPrice ? Number(editPrice) : null,
        image_url: editImageUrl,
      })
      .eq("id", id);
    setEditId(null);
    setEditName("");
    setEditDescription("");
    setEditPrice("");
    setEditImageUrl("");
    await fetchPerfumes();
    setLoading(false);
  }

  return (
    <>
      <NavBar />
      <div className="min-h-screen bg-background pt-24">
        <div className="container mx-auto px-4 py-16">
          <h1 className="font-serif text-3xl mb-8 text-center">
            CRUD Perfumes (productos)
          </h1>
          <div className="mb-8 flex flex-col md:flex-row gap-4 items-center">
            {formError && (
              <div className="text-red-500 text-sm text-center w-full mb-2">{formError}</div>
            )}
            <input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Nombre"
              className="border px-2 py-1"
            />
            <input
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Descripción"
              className="border px-2 py-1"
            />
            <input
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              placeholder="Precio"
              type="number"
              className="border px-2 py-1"
            />
            {/* Componente para subir imagen */}
            <ImageUploaderWithUrl setImageUrl={setImageUrl} />
            <Button onClick={addPerfume} disabled={loading}>
              Agregar
            </Button>
          </div>
          <ul className="space-y-4">
            {perfumes.map((p: any) => (
              <li
                key={p.id}
                className="flex flex-col md:flex-row justify-between items-center border p-2 rounded gap-2"
              >
                {editId === p.id ? (
                  <div className="flex gap-2 w-full">
                    <input
                      value={editName}
                      onChange={(e) => setEditName(e.target.value)}
                      className="border px-2 py-1"
                    />
                    <input
                      value={editDescription}
                      onChange={(e) => setEditDescription(e.target.value)}
                      className="border px-2 py-1"
                    />
                    <input
                      value={editPrice}
                      onChange={(e) => setEditPrice(e.target.value)}
                      type="number"
                      className="border px-2 py-1"
                    />
                    <input
                      value={editImageUrl}
                      onChange={(e) => setEditImageUrl(e.target.value)}
                      className="border px-2 py-1"
                    />
                    <Button
                      variant="outline"
                      onClick={() => updatePerfume(p.id)}
                      disabled={loading}
                    >
                      Guardar
                    </Button>
                    <Button
                      variant="ghost"
                      onClick={() => setEditId(null)}
                    >
                      Cancelar
                    </Button>
                  </div>
                ) : (
                  <div className="flex gap-2 w-full justify-between items-center">
                    <span>
                      {p.name} - {p.description} - ${p.price} <br />
                      <img
                        src={p.image_url}
                        alt="img"
                        className="h-12 inline-block"
                      />
                    </span>
                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        onClick={() => {
                          setEditId(p.id);
                          setEditName(p.name);
                          setEditDescription(p.description);
                          setEditPrice(p.price);
                          setEditImageUrl(p.image_url);
                        }}
                        disabled={loading}
                      >
                        Editar
                      </Button>
                      <Button
                        variant="outline"
                        onClick={() => deletePerfume(p.id)}
                        disabled={loading}
                      >
                        Eliminar
                      </Button>
                    </div>
                  </div>
                )}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </>
  );
}
